import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"困","description":"东坡易传 - 困","frontmatter":{"title":"困","description":"东坡易传 - 困"},"headers":[],"relativePath":"zh/classics/dongpo/048.md","filePath":"zh/classics/dongpo/048.md"}'),o={name:"zh/classics/dongpo/048.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><p>“困”：亨，貞大人吉，無咎；有言不信。</p><p>《彖》曰：“困”，剛揜也。險以說，困而不失其所亨，其唯君子乎？“貞大人吉”，以剛中也。“有言不信”，尚口乃窮也。</p><p>九二爲初六、六三之所揜，九四、九五爲六三、上六之所揜，故“困”。“困”者坐而見制，無能爲之辭也。陰之害陽者多矣，然皆有以侵之；夫惟侵之，是以陽不能堪而至於戰。戰者有危道也，而無所謂“困”。“困”之世，惟不見侵，而見揜。陰有以消陽，而陽無所致其怒，其爲害也深矣。剛中者，二也；二之謂大人。“貞”於“大人”而後“吉”者，五也。</p><p>象曰：澤無水，“困”；君子以致命遂志。</p><p>“水”，潤下者也。在“澤”上則居，在“澤”下則逝矣。故“水”在“澤”下，爲“澤無水”，命與志不相謀者也，故各致其極，而任其所至也。</p><p>初六：臀困於株木，入於幽谷，三歲不覿。象曰：“入於幽谷”，幽不明也。</p><p>初六，揜九二者也。揜者非一人之所能，故初六之揜九二，必將有待於六三。六三固以初爲“臀”也①，“臀”得其所據而後其身能有所爲。今六三之所據者，“蒺藜”也，則臀已困於株木，身且廢矣。“株木”也，“蒺藜”也，皆非臀之所據者也。夫以柔助剛，則其幽可明；以柔揜剛，其誰明之？“入谷”者也，有配在四而不善二，是以“三歲”不得見也。</p><p>【校注】 ① 六三固以初爲臀也：《蘇氏易傳》作“六三則其所謂臀也”，誤。</p><p>九二：困於酒食，朱紱方來，利用享祀；徵兇，無咎。象曰：“困於酒食”，中有慶也。</p><p>“困”之世，利以柔用剛。二與五皆剛者也，二以柔用之，而五以剛用之。天下之易懷者，惟小人也；方其見揜也，爭之以力，雖刀鋸有不足；而將懷之也，則酒食有餘矣，故九二“困於酒食”，所以懷小人也。九五則不然：揜我下者，我劓之；揜我上者，我刖之；輕用其威，威窮而物不服，乃大困也。既困而無助①，則雖欲不求二不可得矣。“赤紱”者，所以爵命二也，故曰困於“赤紱”。五以赤紱爲困，而二以是爲方來，言此五之所困，而二之所不求而至也。困而求二，乃徐有說，以其用說爲已晚矣。說於未困，則其所以爲說者小，故九二之所困者，酒食而已；說於已困，則其所以爲說者重，故九五之所困者，爵命也。祭祀者，人之求神而神無求也。祭之者，人也；享之者，神也。五求二，故祭之；二不求五，故享之而已。享之者固不徵，而徵以求之，故“兇”。雖然，其義則不可咎，以其所從者君也。</p><p>【校注】 ① 困而無助：《蘇氏易傳》作“困則無助”，誤。</p><p>六三：困於石，據於蒺藜；入於其宮，不見其妻，兇。象曰：“據於蒺藜”，乘剛也；“入於其宮，不見其妻”，不祥也。</p><p>六三，上揜四、下揜二者也。堅而不可勝者，石也；四之謂“石”。傷而不可據者，“蒺藜”也，二之謂“蒺藜”。六三陰也，而居於陽，自以爲陽，而求配於上六，“不祥”也。三之應在上，而上六非其應也，“宮”則是矣，而非其“妻”。故曰：“入於其宮，不見其妻，兇。”小人易合而難久，故“困”之三陰，其始相與締交而揜剛，其終初六之“臀”困，六三之“妻”亡。</p><p>九四：來徐徐，困於金車，吝；有終。象曰：“來徐徐”，志在下也；雖不當位，有與也。</p><p>初六我之配，二之所惡也。二剛而在下，載己者也，故爲“金車”。欲下從初六而困於二，故其來“徐徐”，不急於配。配之所怨，剛之所與也，故雖“吝”而“有終”。</p><p>九五：劓、刖，困於赤紱，乃徐有說，利用祭祀。象曰：“劓、刖”，志未得也；“乃徐有說”，以中直也；“利用祭祀”，受福也。</p><p>其曰“赤紱”，正也；“朱紱”，嚴之也；下受上之辭也。“用”，九二也。</p><p>上六：困於葛蘲，於臬危兀危；曰：動悔，有悔；徵吉。象曰：“困於葛蘲”，未當也。 “動悔有悔”，吉行也。</p><p>柔而牽己者，葛蘲也；三之謂“葛蘲”。剛而難乘者，臬危兀危也；五之謂“臬危兀危 ”。上六困於此二者而不能去，則謀全之過也。曰：不可動，動且有悔，而不知其不動乃所以有悔也。上無揜我者，則吉莫如徵也，而不徵，何哉！以柔用剛，則乘之者至以爲“蒺藜”；以剛用剛，則乘之者以爲“臬危兀危 ”而已。上六足以爲配，而六三未足以當也。</p>',20)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
